for key,items in plan.items():
    x=sec[key]; nodes=x['flow']['nodes']; ids=set(nodes)
    for (nid,col,sent,lab,sub,comp,al,desc,why,frm,kind,elab) in items:
        ys=[v[1] for v in list(nodes.values())+list(add_nodes.get(key,{}).values()) if v[0]==col]
        y=(max(ys)+84) if ys else 40
        add_nodes.setdefault(key,{})[nid]=[col,y,sent,lab,sub]
        add_meta.setdefault(key,{})[nid]={"companies":[[c,"関連"] for c in comp],"aliases":al,"desc":desc,"why":why}
        if frm:
            fc=nodes[frm][0] if frm in nodes else add_nodes[key][frm][0]
            if fc<col: add_edges.setdefault(key,[]).append([frm,nid,kind,elab])
            else: add_edges.setdefault(key,[]).append([nid,frm,kind,elab]) if col<fc else None
